<script>
(function () {
  'use strict';
  var cur, last;
  try { cur = getCurrentMessageId(); } catch (e) {}
  try { last = getLastMessageId(); } catch (e) {}
  function num(x) { var n = Number(x); return isNaN(n) ? null : n; }
  var curN = num(cur), lastN = num(last);
  // 仅最新楼显示；旧楼自毁（避免历史楼层堆叠页签）
  if (curN === null || lastN === null || curN !== lastN) { document.body.innerHTML = ''; return; }

  function getPath(obj, path) {
    var parts = String(path).split('.'), o = obj;
    for (var i = 0; i < parts.length; i++) {
      if (o == null) return undefined;
      o = o[parts[i]];
    }
    return o;
  }
  // 扫描最近 80 楼的楼层变量快照，按 世界.当前地点 变化切分为旅程段
  var SCAN = 80;
  var start = Math.max(0, lastN - SCAN);
  var segs = [];
  var prev = null;
  for (var f = start; f <= lastN; f++) {
    var place = '', date = '';
    try {
      var v = getVariables({ type: 'message', message_id: f });
      place = String(getPath(v, 'stat_data.世界.当前地点') || getPath(v, 'stat_data.世界.当前位置') || '');
      date = String(getPath(v, 'stat_data.世界.日期') || '');
    } catch (e) {}
    place = place.replace(/\s+/g, '');
    if (!place || place === '""') continue;
    if (place !== prev) { segs.push({ floor: f, place: place, date: date }); prev = place; }
  }
  // 找当前楼所在段
  var nowSeg = 0;
  for (var s = 0; s < segs.length; s++) { if (segs[s].floor <= lastN) nowSeg = s; }
  var curPlace = segs.length ? segs[nowSeg].place : '';
  var elCur = document.getElementById('pt-tab-cur');
  if (elCur && curPlace) elCur.textContent = '· ' + curPlace;

  var box = document.getElementById('pt-tab-chips');
  if (!segs.length) { box.innerHTML = '<div class="pt-tab-empty">暂无旅程记录</div>'; }
  else {
    var html = '';
    for (var t = 0; t < segs.length; t++) {
      var g = segs[t];
      var dm = String(g.date || '').match(/(\d+)年\s*(\d+)?/);
      var tip = dm ? (dm[1] + '年' + (dm[2] ? dm[2] + '月' : '')) : '';
      html += '<span class="pt-chip' + (t === nowSeg ? ' now' : '') + '" data-floor="' + g.floor + '" title="跳转到第 ' + g.floor + ' 楼">'
        + (t === nowSeg ? '<span class="fl">◈</span>' : '')
        + '<span class="nm">' + g.place + '</span>'
        + (tip ? '<span class="fl">' + tip + '</span>' : '')
        + '</span>';
    }
    box.innerHTML = html;
    var chips = box.querySelectorAll('.pt-chip');
    for (var c = 0; c < chips.length; c++) {
      chips[c].addEventListener('click', function () {
        var fl = this.getAttribute('data-floor');
        try {
          triggerSlash('/go ' + fl);
          var wrap = document.getElementById('pt-tab-wrap');
          if (wrap) wrap.classList.remove('open');
        } catch (e) {}
      });
    }
  }
  var btn = document.getElementById('pt-tab-btn');
  var wrap2 = document.getElementById('pt-tab-wrap');
  if (btn && wrap2) btn.addEventListener('click', function () { wrap2.classList.toggle('open'); });
})();
</script>
